ref_dict.thm:main:
\begin{thm}\label{thm:main}
Let $i$ be a special (cominuscule) node of the Dynkin diagram of $G,$
and $\miw{i}$ the Seidel element corresponding to $i$. Then,  for any $w\in W,$ we have 
    $$
\CO^{\miw{i}}\cdot \miw{i}^L{\CO^w}=Q^{\piv_i-w^{-1}(\piv_i)}\CO^{\miw{i} w}
$$
 in torus-equivatiant quantum $K$-theory $QK_T(G/B)$. 
\end{thm}

ref_dict.thm:Kato:
\begin{thm}[Kato \cite{Kato}, see also \cite{CL}, \cite{LLMS}]\label{thm:Kato}
There is an injective  homomorphism of $R(T)$-algebra 
$\Phi: K_*^T(\Gr_G)_\loc\rightarrow QK_T(G/B)_{\mathrm{loc}}$ such that
\begin{align}
\OGr_{t_\beta}&\mapsto Q^{\beta}\quad \text{for anti-dominant $\beta\in Q^\lor$,}\label{eq:Phi ell}
\\
\bO^w&\mapsto \CO^w\quad\text{for $w\in W$}.
\label{eq:Phi Q}
\end{align}
In particular, we have
\begin{equation}
\label{eq:Qk}
{\prod_{j\in I}\sigma_j^{-\langle \alpha_k^\lor,\alpha_j\rangle}}\mapsto Q_k\quad (k\in I).
\end{equation}
\end{thm}

expanded_sketch:
Our proof relies on the ``quantum equals affine'' philosophy, which goes
back to Peterson \cite{Pet}. A central ingredient is the $K$-theoretic Peterson isomorphism, conjectured in \cite{LLMS} and established by Kato \cite{Kato}, yielding an isomorphism of $R(T)$-algebras. We first recall the following theorem.

\begin{thm}[Kato \cite{Kato}, see also \cite{CL}, \cite{LLMS}]\label{thm:Kato}
There is an injective  homomorphism of $R(T)$-algebra 
$\Phi: K_*^T(\Gr_G)_\loc\rightarrow QK_T(G/B)_{\mathrm{loc}}$ such that
\begin{align}
\OGr_{t_\beta}&\mapsto Q^{\beta}\quad \text{for anti-dominant $\beta\in Q^\lor$,}\label{eq:Phi ell}
\\
\bO^w&\mapsto \CO^w\quad\text{for $w\in W$}.
\label{eq:Phi Q}
\end{align}
In particular, we have
\begin{equation}
\label{eq:Qk}
{\prod_{j\in I}\sigma_j^{-\langle \alpha_k^\lor,\alpha_j\rangle}}\mapsto Q_k\quad (k\in I).
\end{equation}
\end{thm}

Thus we have an isomorphism of $R(T)$-algebras
\[
\Phi:
K_*^T(\Gr_G)_{\mathrm{loc}}\xrightarrow{\ \sim\ } QK_T(G/B)_{\mathrm{loc}}.
\]
We also use an extended version of the $K$-theoretic nil-Hecke algebra developed by Ikeda--Shimozono--Yamaguchi \cite{ISY}: inside their algebra $\hat{\mathbb{K}}_{\mathrm{af}}$ they define a commutative subalgebra $\ePet$ (the extended $K$-theoretic Peterson algebra), an algebraic model for $K_*^{T^{\mathrm{ad}}}(\Gr_{G^{\mathrm{ad}}})$, equipped with a natural action of $\hat{\mathbb{K}}_{\mathrm{af}}$ incorporating the $\hat{W}_{\mathrm{af}}$-symmetry (in particular $\Sigma\simeq \pi_1(G^{\mathrm{ad}})$). The minimal facts needed for establishing the main theorem are reviewed in \S\ref{sec:ePet}, and the proof of the Seidel product formula is given in \S\ref{sec:proof}.

ref_dict.prop3:
\begin{property}\normalfont\label{prop3}
			Let $\gcd(\theta,p)=1$. Assume that $\chi_p:\{\xi\in\mathbb{Z}:\gcd(\xi,p)=1\}\to\{-1,1\}$ is a function (e.g., the Legendre symbol) and suppose that
			$$\zeta_p(\theta)=\frac{1+\chi_p(\theta)}{2}.$$
			Thus, $\chi_p(\theta_1\theta_2)=\chi_p(\theta_1)\chi_p(\theta_2)$.
		\end{property}

ref_dict.prop2:
\begin{property}\normalfont\label{prop2}
			If $A_i=\{a:\zeta_p(a)=i,\ 1\leq a\leq p-1\}$ for $i=0,1$, then $|A_0|=|A_1|$. Hence, $|A_0|=|A_1|=\frac{p-1}{2}$.
		\end{property}

post_theorem_intro_text:
\begin{property}\normalfont\label{prop2}
			If $A_i=\{a:\zeta_p(a)=i,\ 1\leqslant a\leqslant p-1\}$ for $i=0,1$, then $|A_0|=|A_1|$. Hence, $|A_0|=|A_1|=\frac{p-1}{2}$.
		\end{property}

		\begin{property}\normalfont\label{prop3}
			Let $\gcd(\theta,p)=1$. Assume that $\chi_p:\{\xi\in\mathbb{Z}:\gcd(\xi,p)=1\}\to\{-1,1\}$ is a function (e.g., the Legendre symbol) and suppose that
			$$\zeta_p(\theta)=\frac{1+\chi_p(\theta)}{2}.$$
			Thus, $\chi_p(\theta_1\theta_2)=\chi_p(\theta_1)\chi_p(\theta_2)$.
		\end{property}

		\hspace{1cm} For Legendre cordial labeling and Legendre product cordial labeling, observe that if 
		\begin{equation}
			\zeta_p^1(a)=\frac{1+\chi_p(a)}{2}\label{eq0}
		\end{equation}
		where $\chi_p(a)=(a/p)$, then Properties~\ref{prop1}, \ref{prop2}, and \ref{prop3} hold for $\zeta_p^1$ (see Theorem 2.9 in \cite{Andoyo2} and Theorem 2.10 in \cite{Prudencio}). Additionally, for logarithmic cordial labeling, notice that if 
		\begin{equation}
			\ind_{\varpi_1,p}(a)\equiv \zeta_p^2(a)\pmod{2}\label{eq1}
		\end{equation}
		where $\varpi_1$ is a fixed primitive root of $p$, then $\zeta_p^2$ satisfies Properties~\ref{prop1} and \ref{prop2} (see Remarks 2 and 3 in \cite{Andoyo3} with $\eta=p$). Furthermore, let 
		\begin{equation}
			\zeta_p^3(a)=\frac{1+\chi_p(a)}{2}\label{eq2}
		\end{equation}
		with $\chi_p(a)=(-1)^{\ind_{\varpi_2,p}(a)}$, where $\varpi_2$ is a fixed primitive root of $p$. If $a_1\equiv a_2\pmod{p}$ with $\gcd(a_1,p)=\gcd(a_2,p)=1$, then by Remark 2 in \cite{Andoyo3}, we have $\ind_{\varpi_2,p}(a_1)=\ind_{\varpi_2,p}(a_2)$, which means $(-1)^{\ind_{\varpi_2,p}(a_1)}=(-1)^{\ind_{\varpi_2,p}(a_2)}$. Obviously, $\zeta_p^3(a_1)=\zeta_p^3(a_2)$, and so Property~\ref{prop1} holds. Now, assume that 
		$$A_i^2=\{a:\zeta_p^2(a)=i,\ 1\leqslant a\leqslant p-1\},\text{ and }$$
		$$A_i^3=\{a:\zeta_p^3(a)=i,\ 1\leqslant a\leqslant p-1\},$$
		for $i=0,1$ with $\varpi_1=\varpi_2$, where $\zeta_p^2$ is defined in (\ref{eq1}). If $a\in A_0^2$, then $\ind_{\varpi_2,p}(a)\equiv 0\pmod{2}$, and so $\chi_p(a)=1$. Hence, $a\in A_0^3$. Conversely, if $a\in A_0^3$, then 
		\begin{align*}
			1&=\frac{1+\chi_p(a)}{2}\tag{\text{by (\ref{eq2})}}\\
			2&=1+\chi_p(a)\\
			\chi_p(a)&=1\\
			(-1)^{\ind_{\varpi_2,p}(a)}&=1.
		\end{align*}
		Clearly, $\ind_{\varpi_2,p}(a)$ is even. Therefore, $a\in A_0^2$. Thus, $A_i^2=A_i^3$ for $i=0,1$, and it follows that $\zeta_p^3$ satisfies Property~\ref{prop2} since Property~\ref{prop2} holds for $\zeta_p^2$. Lastly, assume that $\gcd(a_1,p)=\gcd(a_2,p)=1$. Using Theorem 9.16 (ii) in \cite{Rosen} (page~369) with $m=p$ and $r=\varpi_2$, 
		$$\ind_{\varpi_2,p}(a_1a_2)\equiv \ind_{\varpi_2,p}(a_1)+\ind_{\varpi_2,p}(a_2)\pmod{(p-1)}.$$
		Since $p-1$ is even, we have 
		$$\ind_{\varpi_2,p}(a_1a_2)\equiv \ind_{\varpi_2,p}(a_1)+\ind_{\varpi_2,p}(a_2)\pmod{2},$$
		which means that $\ind_{\varpi_2,p}(a_1a_2)$ and $\ind_{\varpi_2,p}(a_1)+\ind_{\varpi_2,p}(a_2)$ have the same parity. Consequently,
		\begin{align*}
			\chi_p(a_1a_2)&=(-1)^{\ind_{\varpi_2,p}(a_1a_2)}\\
			&=(-1)^{\ind_{\varpi_2,p}(a_1)+\ind_{\varpi_2,p}(a_2)}\\
			&=(-1)^{\ind_{\varpi_2,p}(a_1)}(-1)^{\ind_{\varpi_2,p}(a_2)}\\
			&=\chi_p(a_1)\chi_p(a_2).
		\end{align*}
		Hence, Property~\ref{prop3} holds. Additionally, the function 
		$$\zeta_p^4(a)=\frac{1-\chi(a)}{2},$$
		where $\chi_p(a)=(a/p)$, also satisfies Properties~\ref{prop1}, \ref{prop2}, and \ref{prop3} with the same explanation as $\zeta_p^1$ defined in (\ref{eq0}).

		\hspace{1cm} As we observed, several functions satisfy Properties~\ref{prop1}, \ref{prop2}, and/or \ref{prop3}. Motivated by this, this paper explores the arithmetic cordial labeling of some graphs. In Sections~\ref{sec3} and \ref{sec4}, we assume that $\eta=p$ is an odd prime.

