In Section \ref{prelims}, we introduce cluster algebras, maximal green sequences, and bipartite dynamics of cluster algebras, known as \textit{$T$-systems} and \textit{$Y$-systems}.
In Section \ref{sec:maximalGreen}, we prove that for all Zamolodchikov periodic $B$-matrices, the bipartite belt is a maximal green sequence.
In Section \ref{sec:half-periodicity}, we prove the form at the half-period is a permutation of the cluster variables, and observe when it gives the identity permutation.
In Section \ref{sec:coloredMutations}, we observe that in the case of single Dynkin diagrams under a certain global tropical ordering, half-periodicity yields a bijection between almost positive roots and colored tropical mutations, as conjectured in our earlier work \cite{chin}.

\section{Preliminaries}
\label{prelims}

\subsection{Introduction to cluster algebras with coefficients}

An $n\times n$ matrix $B$ is \textit{skew-symmetrizable} if there exists some $c\in \mathbb{R}_{>0}^n$ such that $\forall i, j\in [n]$, $c_ib_{ij} = -c_jb_{ji}$.
In other words, a matrix $B$ is skew-symmetrizable if there exists some nonzero scaling of the rows $c\in \mathbb{R}_{>0}^n$ that makes the matrix skew-symmetric.

\begin{definition}
    Let $I$ be a finite index set.
    \begin{itemize}
        \item[(1)]
            A \textit{semifield} is an abelian multiplicative group $(\mathbb{P}, \oplus, \cdot)$ equipped with addition $\oplus$ which is commutative, associative, and distributive with respect to multiplication in $\mathbb{P}$.
        \item[(2)]
            For an $I$-tuple of variables $y = (y_i)_{i\in I}$, the \textit{universal semifield} $\mathbb{Q}_{sf}(y)$ consists of all rational functions $P(y) / Q(y)$, where $P(y)$ and $Q(y)$ are nonzero polynomials in the $y_i$'s over $\mathbb{Z}_{>0}$, equipped with the usual operations of multiplication and addition.
        \item[(3)]
            For an $I$-tuple of variables $y = (y_i)_{i\in I}$, the \textit{tropical semifield} Trop($y$) is the abelian multiplicative group freely generated by the variables $(y_i)_{i\in I}$, equipped with addition $\oplus$ defined by
            $$\prod_i y_i^{a_i} \oplus \prod_i y_i^{b_i} = \prod_i y_i^{\min(a_i, b_i)}.$$
    \end{itemize}
\end{definition}

\begin{definition}
    A \textit{labeled seed} in field $\mathcal{F}$ is a triple $(x, y, B)$ where
    \begin{itemize}
        \item 
            $B = (b_{ij})$ is an $n\times n$ skew-symmetrizable integer matrix,
        \item 
            $x = (x_1, \dots, x_n)$ is an $n$-tuple of elements in $\mathcal{F}$ forming a \textit{free generating set}; that is, $x_1, \dots, x_n$ are algebraically independent over $\mathbb{QP}$, and $\mathcal{F} = \mathbb{QP}(x_1, \dots, x_n)$,
        \item 
            $y = (y_1, \dots, y_n)$ is an $n$-tuple of algebraically independent elements in $\mathbb{P}$.
    \end{itemize}
\end{definition}
We use the following notation:
\begin{itemize}
    \item 
        $x$ is the (labeled) \textit{cluster} of this seed $(x, B)$,
    \item 
        the elements $x_1, \dots, x_n$ are its \textit{cluster variables},
    \item 
        the elements $y_1, \dots, y_n$ are its \textit{frozen variables} (or \textit{coefficients}),
    \item 
        $B$ is the \textit{exchange matrix}, also known as the $B$-matrix.
\end{itemize}
When the coefficients lie in the tropical semifield Trop($y$), they are called \textit{principal coefficients}.

\begin{definition}
    Let $(x, y, B)$ be a labeled seed. 
    Let $k\in [n]$.
    The \textit{seed mutation} $\mu_k$ in direction $k$ transforms $(x, y, B)$ into the new labeled seed $\mu_k(x, y, B) = (x', y', B')$ defined as follows:
    \begin{itemize}
        \item 
            The cluster $x' = (x_1', \dots, x_n')$ is given by $x_j' = x_j$ for all $j\neq k$, whereas $x_k'$ is determined by the \textit{exchange relation}
            \begin{equation}
            \label{mutationX}
                x_kx_k' = \frac{y_{k}}{1 \oplus y_k}\prod_{b_{ik} > 0} x_i^{|b_{ik}|} + \frac{1}{1\oplus y_k}\prod_{b_{ik} < 0} x_i^{|b_{ik}|}.
            \end{equation}
        \item 
            The coefficients $y' = (y_1', \dots, y_n')$ are given by
            \begin{equation}
            \label{mutationY}
                y_i' = \begin{cases}
                    y_i^{-1} & i = k,\\
                    y_iy_k^{\max(0, b_{ki})}(1\oplus y_k)^{-b_{ki}} & i\neq k.
                \end{cases}
            \end{equation}
        \item  
            The exchange matrix $B' = (b_{ij}')$ is given by
            $$b_{ij}' = \begin{cases}
                -b_{ij} & \text{if }i = k \text{ or } j = k,\\
                b_{ij} + b_{ik}b_{kj} & \text{if } b_{ik}, b_{kj} > 0,\\
                b_{ij} - b_{ik}b_{kj} & \text{if } b_{ik}, b_{kj} < 0,\\
                b_{ij} & \text{otherwise.}
            \end{cases}$$
    \end{itemize}
\end{definition}

\begin{definition}
    Let $(x, y, B)$ be a seed.
    Let $\mathcal{Y}$ be the union of all $\{\frac{y_i}{1\oplus y_i}, \frac{1}{1\oplus y_i}\}$ for every coefficient $y_i$ obtained from any sequence of mutations of this seed.
    Let $\mathcal{X}$ be the set of all cluster variables obtained from any sequence of mutations of this seed.
    The \textit{cluster algebra} $\mathcal{A}$ generated by the seed $(x, y, B)$ is the $\mathbb{ZP}$-subalgebra of the ambient field $\mathcal{F}$ generated by all cluster variables: $\mathcal{A} = \mathbb{ZP}[\mathcal{X}]$.
\end{definition}

In general, $\mathcal{X}$ is an infinite set. When $\mathcal{X}$ is finite, we say the cluster algebra $\mathcal{A}$ is of \textit{finite type}.
The following result introduces an interesting connection between root systems and cluster algebras of finite type.

\begin{theorem}[\cite{fomin}]
\label{fominBijection}
    Let $(B, x, y)$ be a seed of a finite type cluster algebra of type $\Lambda$.
    There is a unique bijection between the almost positive roots of $\Lambda$ and the cluster variables of the cluster algebra generated by $(B, x, y)$, which sends $\alpha\mapsto x[\alpha]$, where
    \[x[\alpha] = \frac{P_{\alpha}(x)}{x^{\alpha}}.\]
    Here, $P_{\alpha}(x)$ is a polynomial over $\mathbb{Z}\mathbb{P}$ with nonzero constant term.
    Moreover, every coefficient of $P_{\alpha}$ is a polynomial in the elements of $\mathcal{Y}$ with positive integer coefficients.
\end{theorem}

expanded_sketch:
To prove the main theorem, the paper proceeds as follows: \begin{theorem}
\label{mainThm}
    Let $(\Gamma, \Delta)$ be a Zamolodchikov periodic $n\times n$ $B$-matrix with Coxeter numbers $h_{\Gamma}, h_{\Delta}$.
    Let $T(t)$ be the $T$-system associated to $(\Gamma, \Delta)$.
    Then for all $i\in [n]$,
    \begin{align*}
        T_i(t + h_{\Gamma} + h_{\Delta}) = T_{\sigma(i)}(t)
    \end{align*}
    for some automorphism $\sigma\in S_n$ of $(\Gamma, \Delta)$ of order at most two.
    When $h_{\Gamma} + h_{\Delta}$ is even, this permutation is bipartite color preserving.
    Otherwise, it is color reversing.
\end{theorem}

Next, we introduce cluster algebras, maximal green sequences, and bipartite dynamics of cluster algebras, known as \textit{$T$-systems} and \textit{$Y$-systems}. We then prove that for all Zamolodchikov periodic $B$-matrices, the bipartite belt is a maximal green sequence. We then prove the form at the half-period is a permutation of the cluster variables, and observe when it gives the identity permutation. Finally, we observe that in the case of single Dynkin diagrams under a certain global tropical ordering, half-periodicity yields a bijection between almost positive roots and colored tropical mutations, as conjectured in our earlier work \cite{chin}.

