\begin{thm} \label{Lions-theo}
For any $s$ in $\R$, the space $\mathcal H_s(\Omega) $  is a RKHS and its two-point kernel $K_s$ is given,  for any pair of $x$ and $y$ in $\Omega$,  by 
 \begin{equation} \label{l-formu}
 K_s (x,y)=  \int_{\partial\Omega} \Big((M^{-\frac{s}{2}} \, \gamma_N \big((G_1(x,\cdot)\big)\Big)(z) \, \Big(M^{-\frac{s}{2}} \, \gamma_N \big((G_1(y,\cdot)\big) \Big)(z)\,d\sigma(z) .
 \end{equation}
\end{thm}

ref_dict.defRKHS:
\begin{Definition} \label{defRKHS}
We say that a Hilbert space $H$ of  real-valued functions defined on  $\Omega$ is a reproducing kernel Hilbert space (RKHS for short) 
 if for any $x$ in $\Omega$, the evaluation mapping $E_x$ defined for any $u$ in $H$ by $E_x (u) = u(x)$ 
is linear and continuous from $H$ to $\R$. Then, we denote by  $K_x$ the unique element in $H$ such that for any $u$ in $H$,  $E_x (u) = \langle u,K_x\rangle $, the inner product of $u$ and $K_x$ in $H$, given by Riesz' theorem. Finally, the two-point kernel is defined for any pair of $x$ and $y$ in $\Omega$  by $K(x,y)= \langle K_x,K_y\rangle $. 
\end{Definition}

expanded_sketch:
Using the Poisson formula
\begin{equation} \label{Cani1}
    u(x)
    = \Big\langle \gamma_D (u),\, M^{-{s}} \,\gamma_N \big( G_1 (x,\cdot)\big) \Big\rangle_s ,
\end{equation}
\begin{equation} \label{REg}
    \forall x \in \Omega, \quad   \forall s \in \R, \quad M^{-\frac{s}{2}} \gamma_N \big(G_1(x,\cdot)\big)  \in L^2 (\partial\Omega) ,
\end{equation}
and the Cauchy--Schwarz inequality, one shows that for any $x\in\Omega$ the evaluation mapping $E_x$ is continuous from $\mathcal H_s(\Omega)$ to $\mathbb R$. Since $\mathcal H_s(\Omega)$ is a Hilbert space, Riesz' theorem yields, for each $x\in\Omega$, an element $K_x\in\mathcal H_s(\Omega)$ such that for all $u\in\mathcal H_s(\Omega)$,
\begin{equation} \label{Cani2}
 u(x) = \langle \gamma_D (u) ,\, K_x \rangle_s = \langle M^{\frac{s}{2}} \, \gamma_D (u) ,\,  M^{\frac{s}{2}} \, K_x \rangle_{L^2 (\partial \Omega)}.
\end{equation}
Combining \eqref{Cani1} with \eqref{Cani2} gives, for any $u\in\mathcal H_s(\Omega)$,
\[
\Big\langle M^{\frac{s}{2}}\gamma_D(u),\, M^{-\frac{s}{2}}\gamma_N\big(G_1(x,\cdot)\big)-M^{\frac{s}{2}}K_x\Big\rangle_{L^2(\partial\Omega)}=0.
\]
By a density argument in $u$, this implies
\[
M^{\frac{s}{2}}K_x = M^{-\frac{s}{2}}\gamma_N\big(G_1(x,\cdot)\big)\quad\text{a.e. on }\partial\Omega.
\]
Therefore, for any $x,y\in\Omega$,
\[
K_s(x,y)=\langle M^{\frac{s}{2}}K_x,\, M^{\frac{s}{2}}K_y\rangle_{L^2(\partial\Omega)}
=\Big\langle M^{-\frac{s}{2}}\gamma_N\big(G_1(x,\cdot)\big),\, M^{-\frac{s}{2}}\gamma_N\big(G_1(y,\cdot)\big)\Big\rangle_{L^2(\partial\Omega)},
\]
which is exactly
\begin{equation} \label{l-formu}
 K_s (x,y)=  \int_{\partial\Omega} \Big((M^{-\frac{s}{2}} \, \gamma_N \big((G_1(x,\cdot)\big)\Big)(z) \, \Big(M^{-\frac{s}{2}} \, \gamma_N \big((G_1(y,\cdot)\big) \Big)(z)\,d\sigma(z) .
 \end{equation}
.

