\begin{theorem}\label{mainthm}
    Let $X$ be an affine curve and $Y$ be a projective curve over $\overline{\mathbb{Q}}$. Let $f:X\to X$ and $g:Y\to Y$ be endomorphisms. Then DML conjecture holds for $(X\times Y, f\times g)$.
\end{theorem}

