\begin{theorem}[{\cite[Theorem~3.4]{EndoHongUlrich}}]\label{EGHU}
Let $A = k[x_1, x_2, \ldots, x_d]$ be a polynomial ring over a field $k$ of characteristic zero.
Let $I$ be a zero-dimensional ideal of $A$ generated by $d+3$ homogeneous polynomials.
If $I$ is integrally closed, then $I$ is normal. 
\end{theorem}

